#!/usr/bin/env python3
"""Tier R generator: intrinsic database -> strongly-typed, feature-gated C++ wrappers.

Each wrapper is a template over a lane Target with a `requires Has<T, feature>` clause, so using an
intrinsic the target lacks is a compile error naming the feature, not a SIGILL in the field."""
import argparse, json, re

FEAT = {"sse": "sse2", "ssse3": "sse4_2", "sse4_1": "sse4_2"}  # folded into our tag set
TAG = {"fma": "fma3"}  # caps.hpp tag names that differ from the raw:: namespace name

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--db"); ap.add_argument("--out")
    a = ap.parse_args()
    db = json.load(open(a.db))
    groups = {}
    for e in db["intrinsics"]:
        f = FEAT.get(e["feature"], e["feature"])
        groups.setdefault(f, []).append(e)
    L = ["// GENERATED by ops/gen/intrin_gen.py from ops/intrinsics/x86.json — do not edit.",
         "#pragma once", "#include <forge/simd/caps.hpp>", "#if defined(__x86_64__) || defined(_M_X64)", "#include <immintrin.h>",
         "", "namespace forge::simd::raw::x86 {", "",
         f"inline constexpr int intrinsic_count = {len(db['intrinsics'])};", ""]
    imm_re = re.compile(r"^const int$")
    for f in sorted(groups):
        L.append(f"namespace {f} {{")
        for e in groups[f]:
            name = e["name"]; wname = name.lstrip("_")
            ps = e["params"]
            # immediates must be compile-time: lift to template parameters
            tparams = ["::forge::simd::Target T"]
            args, call = [], []
            for i, t in enumerate(ps):
                if imm_re.match(t):
                    tparams.append(f"int I{i}"); call.append(f"I{i}")
                else:
                    args.append(f"{t} a{i}"); call.append(f"a{i}")
            imm_first = [tp for tp in tparams[1:]]
            tpl = ", ".join(imm_first + [tparams[0]])
            ret = "" if e["ret"] == "void" else "return "
            L.append(f"template <{tpl}> requires ::forge::simd::Has<T, ::forge::simd::{TAG.get(f, f)}>")
            L.append(f"[[gnu::always_inline]] inline {e['ret']} {wname}({', '.join(args)}) {{ {ret}{name}({', '.join(call)}); }}")
        L.append(f"}} // namespace {f}")
        L.append("")
    L += ["} // namespace forge::simd::raw::x86", "#endif", ""]
    open(a.out, "w", encoding="utf-8", newline="\n").write("\n".join(L))

if __name__ == "__main__":
    main()
